   261          label[x] = 0;           /* Always terminate w/ a 0 */
   262
   263          /* Double-loop checking each label against all m->_labels for match */
   264          for (x = 0; label[x]; x += label[x] + 1) {
   265                  for (y = 0; y < MAX_NUM_LABELS && m->_labels[y]; y++) {
   266                          if (_lmatch(m, label + x, m->_labels[y])) {
   267                                  /* Matching label, set up pointer */
   268                                  l = label + x;
   269                                  short2net((unsigned short)((unsigned char *)m->_labels[y] - m->_packet), (unsigned char **)&l);
   270                                  label[x] = (char)(label[x] | 0xc0);
   271                                  len = x + 2;
   272                                  break;
   273                          }
   274                  }
   275
   276                  if (label[x] & 0xc0)
   277                          break;
   278          }
   279
   280          /* Copy into buffer, point there now */
   281          memcpy(*bufp, label, (size_t)len);
   282          l = (char *)*bufp;
   283          *bufp += len;
   284
   285          /* For each new label, store it's location for future compression */
   286          for (x = 0; l[x] && m->_label < MAX_NUM_LABELS; x += l[x] + 1) {
   287                  if (l[x] & 0xc0)
   288                          break;
   289
   290                  m->_labels[m->_label++] = l + x;
   291          }
   292
   293          return len;
   294  }
