   296  static bool _rrparse(struct message *m, struct resource *rr, int count, const unsigned char **bufp, const unsigned char* bufferEnd)
   297  {
   298          int i;
   299      const unsigned char *addr_bytes = NULL;
   300
   301      if (count == 0) {
   302          return true;
   303      }
   304
   305      if (*bufp >= m->_bufEnd) {
   306          return false;
   307      }
   308
   309          for (i = 0; i < count; i++) {
   310              if (*bufp >= bufferEnd) {
   311              return false;
   312          }
   313
   314                  if (!_label(m, bufp, bufferEnd, &(rr[i].name))) {
   315              return false;
   316          }
   317                  if (*bufp + 10 > bufferEnd) {
   318              return false;
   319          }
   320                  rr[i].type     = net2short(bufp);
   321                  rr[i].clazz    = net2short(bufp);
   322                  rr[i].ttl      = net2long(bufp);
   323                  rr[i].rdlength = net2short(bufp);
   324  //              fprintf(stderr, "Record type %d class 0x%2x ttl %lu len %d\n", rr[i].type, rr[i].clazz, rr[i].ttl, rr[i].rdlength);
   325
   326                  /* For the following records the rdata will be parsed later. So don't set it here:
   327                   * NS, CNAME, PTR, DNAME, SOA, MX, AFSDB, RT, KX, RP, PX, SRV, NSEC
   328                   * See 18.14 of https://tools.ietf.org/html/rfc6762#page-47 */
   329                  if (rr[i].type == QTYPE_NS || rr[i].type == QTYPE_CNAME || rr[i].type == QTYPE_PTR || rr[i].type == QTYPE_SRV) {
   330                          rr[i].rdlength = 0;
   331                  } else {
   332              /* If not going to overflow, make copy of source rdata */
   333              if (*bufp + rr[i].rdlength > bufferEnd) {
   334                  return false;
   335              }
   336
   337                          rr[i].rdata = m->_packet + m->_len;
   338              if (m->_len + rr[i].rdlength > MAX_PACKET_LEN) {
   339                  return false;
   340              }
   341                          m->_len += rr[i].rdlength;
   342                          memcpy(rr[i].rdata, *bufp, rr[i].rdlength);
   343                  }
   344
   345
   346                  /* Parse commonly known ones */
   347                  switch (rr[i].type) {
   348                  case QTYPE_A:
   349                          if (m->_len + 16 > MAX_PACKET_LEN) {
   350                  return false;
   351              }
   352                          rr[i].known.a.name = (char *)m->_packet + m->_len;
   353                          m->_len += 16;
   354              if (*bufp + 4 > bufferEnd) {
   355                  return false;
   356              }
   357                          msnds_snprintf(rr[i].known.a.name,16, "%d.%d.%d.%d", (*bufp)[0], (*bufp)[1], (*bufp)[2], (*bufp)[3]);
   358                          addr_bytes = (const unsigned char *) *bufp;
   359                          rr[i].known.a.ip.s_addr = (in_addr_t) (
   360                                          ((in_addr_t) addr_bytes[0]) |
   361                                          (((in_addr_t) addr_bytes[1]) << 8) |
   362                                          (((in_addr_t) addr_bytes[2]) << 16) |
   363                                          (((in_addr_t) addr_bytes[3]) << 24));
   364              *bufp += 4;
   365                          break;
   366
   367                  case QTYPE_NS:
   368                          if (!_label(m, bufp, bufferEnd, &(rr[i].known.ns.name))) {
   369                  return false;
   370              }
   371                          break;
   372
   373                  case QTYPE_CNAME:
   374                          if (!_label(m, bufp, bufferEnd, &(rr[i].known.cname.name))) {
   375                  return false;
   376              }
   377                          break;
   378
   379                  case QTYPE_PTR:
   380                          if (!_label(m, bufp, bufferEnd, &(rr[i].known.ptr.name))) {
   381                  return false;
   382              }
   383                          break;
   384
   385                  case QTYPE_SRV:
   386              if (*bufp + 6 > bufferEnd) {
   387                  return false;
   388              }
   389                          rr[i].known.srv.priority = net2short(bufp);
   390                          rr[i].known.srv.weight = net2short(bufp);
   391                          rr[i].known.srv.port = net2short(bufp);
   392                          if (!_label(m, bufp, bufferEnd, &(rr[i].known.srv.name))) {
   393                  return false;
   394              }
   395                          break;
   396
   397                  case QTYPE_TXT:
   398                  default:
   399                          *bufp += rr[i].rdlength;
   400                  }
   401          }
   402
   403          return true;
   404  }
