   406  /* Keep all our mem in one (aligned) block for easy freeing */
   407  #define my(x,y, cast)                           \
   408          while (m->_len & 7)                     \
   409                  m->_len++;                      \
   410                                          \
   411      if (m->_len + y > MAX_PACKET_LEN) { return false; } \
   412          x = (cast)(void *)(m->_packet + m->_len);       \
   413          m->_len += y;
