   582  void message_rdata_raw(struct message *m, unsigned char *rdata, unsigned short int rdlength)
   583  {
   584          if (((unsigned char *)m->_buf - m->_packet) + rdlength > 4096)
   585                  rdlength = 0;
   586          short2net(rdlength, &(m->_buf));
   587          memcpy(m->_buf, rdata, rdlength);
   588          m->_buf += rdlength;
