   591  unsigned char *message_packet(struct message *m)
   592  {
   593          unsigned char c, *buf = m->_buf, *bufEnd = m->_bufEnd;
   594
   595          m->_buf = m->_packet;
   596      m->_bufEnd = m->_packet + sizeof(m->_packet);
   597          short2net(m->id, &(m->_buf));
   598
   599          if (m->header.qr)
   600                  m->_buf[0] |= 0x80;
   601          if ((c = (unsigned char)m->header.opcode))
   602                  m->_buf[0] |= (unsigned char)(c << 3);
   603          if (m->header.aa)
   604                  m->_buf[0] |= 0x04;
   605          if (m->header.tc)
   606                  m->_buf[0] |= 0x02;
   607          if (m->header.rd)
   608                  m->_buf[0] |= 0x01;
   609          if (m->header.ra)
   610                  m->_buf[1] |= 0x80;
   611          if ((c = (unsigned char)m->header.z))
   612                  m->_buf[1] |= (unsigned char)(c << 4);
   613          if (m->header.rcode)
   614                  m->_buf[1] = (unsigned char)(m->_buf[1] | m->header.rcode);
   615
   616          m->_buf += 2;
   617          short2net(m->qdcount, &(m->_buf));
   618          short2net(m->ancount, &(m->_buf));
   619          short2net(m->nscount, &(m->_buf));
   620          short2net(m->arcount, &(m->_buf));
